!function(){"use strict";jQuery(window).on("elementor/frontend/init",()=>{elementorFrontend.hooks.addAction("frontend/element_ready/omero-button.default",e=>{if(elementorFrontend.elementsHandler.addHandler(omeroButtonInit,{$element:e}),e.hasClass("omero-button-popup-yes")){var n=new elementorModules.frontend.handlers.Base({$element:e}).getElementSettings("popup_type"),t=e.find("a.elementor-button");if(t.length)switch(n){case"default":t.magnificPopup();break;case"image":break;default:t.magnificPopup({type:n})}}})})}();